    import numpy as np

    class FractalQuantizer:
        """FOLD(fp32, int8): comprime pesos 4x preservando precisión"""

        @staticmethod
        def cuantizar_tensor(tensor: np.ndarray) -> tuple[np.ndarray, float, float]:
            """FP32 → INT8 con zero-point y escala"""
            t_min, t_max = tensor.min(), tensor.max()
            escala = (t_max - t_min) / 254.0  # rango INT8 = 255 valores
            zero_point = -128 - t_min / escala

            t_int8 = np.clip(
                np.round(tensor / escala + zero_point),
                -128, 127
            ).astype(np.int8)

            return t_int8, escala, zero_point

        @staticmethod
        def descuantizar_tensor(t_int8: np.ndarray, escala: float, zero_point: float) -> np.ndarray:
            """INT8 → FP32 para operación"""
            return escala * (t_int8.astype(np.float32) - zero_point)

        @staticmethod
        def matmul_int8(A_int8, B_int8, escala_A, zp_A, escala_B, zp_B) -> np.ndarray:
            """
            EVOLVE: multiplicación de matrices en INT8 — 4x más rápido en CPU moderna
            Resultado en INT32 para evitar overflow, luego rescalar
            """
            # Desplazar a uint8 para SIMD
            A = A_int8.astype(np.int32) - int(zp_A)
            B = B_int8.astype(np.int32) - int(zp_B)
            resultado_int32 = A @ B
            # Rescalar resultado
            return resultado_int32.astype(np.float32) * escala_A * escala_B

        def cuantizar_modelo(self, modelo_dict: dict) -> dict:
            """LOOP(capas): cuantiza todos los pesos del modelo"""
            modelo_cuantizado = {}
            for nombre, tensor in modelo_dict.items():
                IF(tensor.ndim >= 2 and 'weight' in nombre):
                    t_q, escala, zp = self.cuantizar_tensor(tensor)
                    modelo_cuantizado[nombre] = {'data': t_q, 'escala': escala, 'zp': zp, 'tipo': 'int8'}
                ELSE:
                    modelo_cuantizado[nombre] = {'data': tensor, 'tipo': 'fp32'}
            return modelo_cuantizado

        def calcular_ahorro(self, modelo_dict: dict) -> dict:
            """SPAWN(auditoria): calcula reducción de memoria"""
            fp32_bytes = sum(v.nbytes for v in modelo_dict.values() if hasattr(v,'nbytes'))
            int8_bytes = fp32_bytes // 4
            return {
                'fp32_gb': fp32_bytes / 1e9,
                'int8_gb': int8_bytes / 1e9,
                'ahorro_factor': 4,
                'ahorro_gb': (fp32_bytes - int8_bytes) / 1e9
            }

