    import re
    import ast

    class FractalCompiler:
        """
        EVOLVE(texto_fractal, ast_python, codigo_ejecutable):
        Traduce el lenguaje fractal de ARKANI a Python puro
        """

        OPERACIONES_FRACTAL = {'SUM', 'IF', 'LOOP', 'SPAWN', 'FOLD', 'LINK', 'EVOLVE'}

        def __init__(self):
            self.scope_local = {}

        def compilar(self, codigo_fractal: str) -> str:
            """LINK(fractal, python): traducción completa"""
            lineas = codigo_fractal.strip().split('\n')
            python_lines = []

            for linea in lineas:
                linea_traducida = self._traducir_linea(linea)
                python_lines.append(linea_traducida)

            return '\n'.join(python_lines)

        def _traducir_linea(self, linea: str) -> str:
            """IF(es_operacion_fractal, traducir, mantener_como_python)"""
            linea_stripped = linea.strip()

            # Detectar si es una operación fractal al inicio
            for op in self.OPERACIONES_FRACTAL:
                if linea_stripped.startswith(f'{op}('):
                    return self._traducir_operacion(linea_stripped, linea)

            # Traducir IF fractal → Python if
            if re.match(r'IF\s*\(', linea_stripped):
                return self._traducir_if(linea_stripped, linea)

            # Traducir LOOP fractal → Python for
            if re.match(r'LOOP\s*\(', linea_stripped):
                return self._traducir_loop(linea_stripped, linea)

            return linea  # código Python normal — pasar sin cambios

        def _traducir_if(self, expr: str, linea_original: str) -> str:
            """EVOLVE: IF(cond, A, B) → if cond: A else: B"""
            # Extraer argumentos respetando paréntesis anidados
            args = self._extraer_args(expr[3:])  # quitar 'IF'
            IF(len(args) >= 2):
                indentacion = len(linea_original) - len(linea_original.lstrip())
                ind = ' ' * indentacion
                cond, entonces = args[0], args[1]
                sino = args[2] if len(args) > 2 else 'None'
                return f'{ind}if {cond}:\n{ind}    {entonces}\n{ind}else:\n{ind}    {sino}'
            return linea_original

        def _traducir_loop(self, expr: str, linea_original: str) -> str:
            """EVOLVE: LOOP(n, op) → for i in range(n): op(i)"""
            args = self._extraer_args(expr[5:])
            IF(len(args) >= 2):
                indentacion = ' ' * (len(linea_original) - len(linea_original.lstrip()))
                n, op = args[0], args[1]
                return f'{indentacion}for _i_ in range({n}):\n{indentacion}    {op}(_i_)'
            return linea_original

        def _extraer_args(self, texto: str) -> list:
            """FOLD: extrae argumentos respetando paréntesis anidados"""
            # Quitar paréntesis externos
            texto = texto.strip()
            if texto.startswith('(') and texto.endswith(')'):
                texto = texto[1:-1]

            args, nivel, inicio, actual = [], 0, 0, []
            for i, c in enumerate(texto):
                if c == '(':
                    nivel += 1
                    actual.append(c)
                elif c == ')':
                    nivel -= 1
                    actual.append(c)
                elif c == ',' and nivel == 0:
                    args.append(''.join(actual).strip())
                    actual = []
                else:
                    actual.append(c)
            if actual:
                args.append(''.join(actual).strip())

            return args

        def ejecutar(self, codigo_fractal: str, contexto: dict = None) -> Any:
            """EVOLVE: compila y ejecuta código fractal directamente"""
            codigo_python = self.compilar(codigo_fractal)
            scope = {**self.scope_local, **(contexto or {})}
            from .operaciones import SUM, IF, LOOP, SPAWN, FOLD, LINK, EVOLVE
            scope.update({'SUM':SUM,'IF':IF,'LOOP':LOOP,'SPAWN':SPAWN,'FOLD':FOLD,'LINK':LINK,'EVOLVE':EVOLVE})
            exec(codigo_python, scope)
            return scope.get('resultado')

